def transform(g):
    H,W=len(g),len(g[0])
    out=[row[:] for row in g]
    seps_r=[r for r in range(H) if len(set(g[r]))==1 and g[r][0]!=0]
    seps_c=[c for c in range(W) if len(set(g[r][c] for r in range(H)))==1 and g[0][c]!=0]
    rb=[0]+[r+1 for r in seps_r]; re=seps_r+[H]
    cb=[0]+[c+1 for c in seps_c]; ce=seps_c+[W]
    for bi in range(len(rb)-1):
        for bj in range(len(cb)-1):
            grids={}
            for di in (0,1):
                for dj in (0,1):
                    ii,jj=bi+di,bj+dj
                    if ii>=len(rb) or jj>=len(cb): continue
                    r0,r1=rb[ii],re[ii]; c0,c1=cb[jj],ce[jj]
                    sub=[row[c0:c1] for row in g[r0:r1]]
                    if any(x for row in sub for x in row): grids[(di,dj)]=sub
            if len(grids)==3:
                colors={x for s in grids.values() for row in s for x in row if x}
                if len(colors)!=1: continue
                miss=[k for k in [(0,0),(0,1),(1,0),(1,1)] if k not in grids][0]
                same_row=[k for k in grids if k[0]==miss[0]]
                same_col=[k for k in grids if k[1]==miss[1]]
                ref,mode=(same_row[0],'h') if same_row else (same_col[0],'v')
                sub=grids[ref]
                fill=[row[::-1] for row in sub] if mode=='h' else sub[::-1]
                di,dj=miss
                r0,r1=rb[bi+di],re[bi+di]; c0,c1=cb[bj+dj],ce[bj+dj]
                for r in range(r0,r1):
                    for c in range(c0,c1):
                        out[r][c]=fill[r-r0][c-c0]
    return out

